from __future__ import annotations

import json
import math
import shutil
import subprocess
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
SOURCE_ROOT = TASK_DIR / "source"
FIXTURE_DIR = TASK_DIR / "fixtures"
MANIFEST_FILE = FIXTURE_DIR / "public_cases.json"
OUTPUT_DIR = TASK_DIR / "outputs"
GENERATED_DIR = OUTPUT_DIR / "generated"
REPORT_FILE = OUTPUT_DIR / "reproduction_report.json"


def octave_quote(value: str) -> str:
    return value.replace("'", "''")


def checkpoint_rows(records: list[dict[str, object]]) -> list[str]:
    rows = []
    for record in records:
        checkpoint = FIXTURE_DIR / str(record["checkpoint"])
        if not checkpoint.is_file():
            raise RuntimeError(f"missing public checkpoint: {checkpoint.name}")
        rows.append(
            "    '%s', '%s'"
            % (
                octave_quote(str(record["record_id"])),
                octave_quote(str(checkpoint)),
            )
        )
    return rows


def write_files(directory: Path, files: dict[str, str]) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    for name, contents in files.items():
        (directory / name).write_text(contents, encoding="utf-8")


def write_model_shims(directory: Path) -> None:
    write_files(
        directory,
        {
            "printLog.m": "function msg = printLog(varargin)\nmsg = '';\nend\n",
            "op_takesubspec.m": (
                "function out = op_takesubspec(in, varargin)\nout = in;\nend\n"
            ),
            "op_ampScale.m": (
                "function out = op_ampScale(in, varargin)\nout = in;\nend\n"
            ),
            "fit_runFit.m": (
                "function [params, basis] = fit_runFit(~, basis, varargin)\n"
                "params = struct('refShift', 0, 'refFWHM', 5);\nend\n"
            ),
            "nlinfit.m": (
                "function params = nlinfit(~, ~, ~, initial)\nparams = initial;\nend\n"
            ),
            "osp_CheckRunPreviousModule.m": (
                "function [has_spm, version] = osp_CheckRunPreviousModule(varargin)\n"
                "has_spm = 1;\nversion = 'task025-offline';\nend\n"
            ),
            "osp_fitInitialise.m": (
                "function out = osp_fitInitialise(in)\nout = in;\nend\n"
            ),
            "osp_fit_Quality.m": (
                "function out = osp_fit_Quality(in)\n"
                "out = in;\n"
                "out.QM = struct();\n"
                "out.QM.tables = struct();\n"
                "out.QM.tables.Properties = struct();\n"
                "out.QM.tables.Properties.VariableNames = {'task025_observation'};\n"
                "out.QM.relAmpl = struct();\n"
                "out.QM.relAmpl.metab_A = 0;\n"
                "out.QM.relAmpl.metab_sum = 0;\n"
                "out.QM.relAmpl.metab_diff1 = 0;\n"
                "out.QM.relAmpl.metab_diff2 = 0;\n"
                "end\n"
            ),
            "osp_WriteBIDsTable.m": ("function osp_WriteBIDsTable(varargin)\nend\n"),
            "save.m": "function save(varargin)\nend\n",
        },
    )


def numeric_summary_function() -> str:
    return r"""
function [value_count, finite_count, sum_squares] = task025_numeric_summary(value)
value_count = 0;
finite_count = 0;
sum_squares = 0;
if isnumeric(value) || islogical(value)
    flat = value(:);
    finite_mask = isfinite(real(flat)) & isfinite(imag(flat));
    value_count = numel(flat);
    finite_count = sum(finite_mask);
    if finite_count == value_count
        sum_squares = sum(abs(flat) .^ 2);
    else
        sum_squares = NaN;
    end
elseif iscell(value)
    for item_idx = 1:numel(value)
        [child_count, child_finite, child_sum] = task025_numeric_summary(value{item_idx});
        value_count = value_count + child_count;
        finite_count = finite_count + child_finite;
        sum_squares = sum_squares + child_sum;
    end
elseif isstruct(value)
    for item_idx = 1:numel(value)
        names = fieldnames(value(item_idx));
        for field_idx = 1:numel(names)
            child = value(item_idx).(names{field_idx});
            [child_count, child_finite, child_sum] = task025_numeric_summary(child);
            value_count = value_count + child_count;
            finite_count = finite_count + child_finite;
            sum_squares = sum_squares + child_sum;
        end
    end
end
end
"""


def write_model_driver(directory: Path, records: list[dict[str, object]]) -> Path:
    driver = r"""function task025_fit_study(output_file)
records = {
__RECORDS__
};
fid = fopen(output_file, 'w');
if fid < 0
    error('Could not open model-study output.');
end
for case_idx = 1:size(records, 1)
    checkpoint = load(records{case_idx, 2});
    container = task025_fit_container(checkpoint, output_file);
    result = OspreyFit(container);
    if ~isfield(result, 'fit') || ~isfield(result.fit, 'resBasisSet')
        error('The high-level fit workflow returned no inspectable result.');
    end
    completed = isfield(result, 'flags') && isfield(result.flags, 'didFit') && result.flags.didFit;
    [value_count, finite_count, sum_squares] = task025_numeric_summary(result.fit.resBasisSet);
    l2_norm = sqrt(sum_squares);
    fprintf(fid, 'edited_model\t%s\t%s\t%d\t%d\t%d\t%.17g\n', ...
        records{case_idx, 1}, task025_text(checkpoint.sequence), completed, ...
        value_count, finite_count, l2_norm);
end
fclose(fid);
end

function container = task025_fit_container(checkpoint, output_file)
sequence = task025_text(checkpoint.sequence);
basis = struct();
basis.t = checkpoint.time;
basis.fids = checkpoint.fids;
basis.ppm = checkpoint.ppm;
basis.specs = checkpoint.specs;
basis.sz = size(basis.fids);
basis.spectralwidth = double(checkpoint.spectral_width(1));
basis.dwelltime = 1 / basis.spectralwidth;
basis.txfrq = double(checkpoint.field_strength(1)) * 42.577;
basis.centerFreq = double(checkpoint.center_ppm(1));
basis.date = 'offline-checkpoint';
basis.dims = struct('t', 1, 'averages', 0, 'subSpecs', 0, 'coils', 0);
basis.Bo = double(checkpoint.field_strength(1));
basis.averages = 1;
basis.rawAverages = 1;
basis.subspecs = 1;
basis.rawSubspecs = 1;
basis.flags = task025_basis_flags();
basis.n = double(checkpoint.points(1));
basis.name = task025_strings(checkpoint.component_names);
basis.names = task025_strings(checkpoint.subspectrum_names);
basis.nMets = double(checkpoint.n_metabolites(1));
basis.nMM = double(checkpoint.n_macromolecules(1));

container = struct();
container.outputFolder = fileparts(output_file);
container.outputFile = 'task025_fit_ignored.mat';
container.nDatasets = 1;
container.flags = struct();
container.flags.isGUI = 0;
container.flags.isPRIAM = 0;
container.flags.isMRSI = 0;
container.flags.isUnEdited = strcmp(sequence, 'unedited');
container.flags.isMEGA = strcmp(sequence, 'MEGA');
container.flags.isHERMES = strcmp(sequence, 'HERMES');
container.flags.isHERCULES = strcmp(sequence, 'HERCULES');
container.flags.hasRef = 0;
container.flags.hasWater = 0;
container.flags.didFit = 0;
container.flags.speedUp = 0;
container.flags.hasMM = 0;
container.ver = struct('Osp', 'checkpoint', 'CheckOsp', 'checkpoint');
container.runtime = struct();
container.opts = struct();
container.opts.savePDF = 0;
container.opts.fit = struct('method', 'Osprey', 'style', 'Separate', ...
    'coMM3', task025_text(checkpoint.model_option), 'FWHMcoMM3', 14, 'MeanMM', 0);
container.opts.fit.GAP = struct('A', 0, 'sum', 0, 'diff1', 0, 'diff2', 0);
container.info.metab.unique_ndatapoint_spectralwidth_ind = 1;
container.info.metab.unique_ndatapoint_spectralwidth = {'spec_1'};
container.fit.basisSet = basis;
container.fit.scale = {1};
container.processed.metab = {struct('sequence', sequence)};
end

function flags = task025_basis_flags()
flags = struct();
flags.writtentostruct = 1;
flags.gotparams = 1;
flags.leftshifted = 0;
flags.filtered = 0;
flags.zeropadded = 0;
flags.freqcorrected = 0;
flags.phasecorrected = 0;
flags.averaged = 0;
flags.addedrcvrs = 0;
flags.subtracted = 0;
flags.writtentotext = 0;
flags.downsampled = 0;
flags.isFourSteps = 0;
end

function values = task025_strings(value)
if iscell(value)
    values = value;
else
    values = cellstr(value);
end
values = values(:)';
for idx = 1:numel(values)
    values{idx} = task025_text(values{idx});
end
end

function value = task025_text(raw)
if iscell(raw)
    raw = raw{1};
end
value = strtrim(char(raw));
end
""" + numeric_summary_function()
    driver = driver.replace("__RECORDS__", ";...\n".join(checkpoint_rows(records)))
    path = directory / "task025_fit_study.m"
    path.write_text(driver, encoding="utf-8")
    return path


def write_project_shims(directory: Path) -> None:
    write_files(
        directory,
        {
            "OspreyJob.m": r"""function container = OspreyJob(job_file, varargin)
checkpoint = load(job_file);
container = struct();

container = struct();
container.outputFolder = fileparts(mfilename('fullpath'));
container.outputFile = 'task025_project_ignored.mat';
container.nDatasets = 1;
container.files_nii = {};
container.files_seg = {};
container.flags = struct();
container.flags.hasRef = 1;
container.flags.hasWater = 0;
container.flags.didSeg = 0;
container.flags.didFit = 1;
container.flags.didQuantify = 0;
container.flags.isGUI = 0;
container.flags.isMRSI = 0;
container.flags.isPRIAM = 0;
container.flags.isUnEdited = 1;
container.flags.isMEGA = 0;
container.flags.isHERMES = 0;
container.flags.isHERCULES = 0;
container.ver = struct('Osp', 'checkpoint', 'CheckOsp', 'checkpoint');
container.opts = struct();
container.opts.fit = struct('method', 'Osprey', 'coMM3', '');
container.info.metab.unique_ndatapoint_spectralwidth = {'spec_1'};
container.info.metab.unique_ndatapoint_spectralwidth_ind = 1;
container.fit.results.metab.fitParams = cell(1, 1, 1);
metabolite_signal = checkpoint.metabolite_signal(1);
container.fit.results.metab.fitParams{1, 1, 1} = struct('ampl', [metabolite_signal; metabolite_signal]);
container.fit.results.ref.fitParams = {struct('ampl', checkpoint.reference_signal(1))};
container.fit.resBasisSet.metab.spec_1 = cell(1, 1, 1);
basis = struct();
basis.name = task025_text(checkpoint.basis_name);
basis.names = {'metab'};
container.fit.resBasisSet.metab.spec_1{1, 1, 1} = basis;
container.raw = {struct('Bo', checkpoint.field_strength(1))};
metabolite = struct('tr', checkpoint.metabolite_tr_ms(1), 'te', checkpoint.metabolite_te_ms(1));
metabolite.names = {'metab'};
reference = struct('tr', checkpoint.reference_tr_ms(1), 'te', checkpoint.reference_te_ms(1));
reference.names = {'metab'};
container.processed.metab = {metabolite};
container.processed.ref = {reference};
end

function value = task025_text(raw)
if iscell(raw)
    raw = raw{1};
end
value = strtrim(char(raw));
