""",
            "OspreyLoad.m": "function out = OspreyLoad(in)\nout = in;\nend\n",
            "OspreyProcess.m": ("function out = OspreyProcess(in)\nout = in;\nend\n"),
            "OspreyFit.m": "function out = OspreyFit(in)\nout = in;\nend\n",
            "OspreyOverview.m": ("function out = OspreyOverview(in)\nout = in;\nend\n"),
