% op_dccorr.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% [out,dcOffset]=op_dccorr(in,mode,var1);
% 
% DESCRIPTION:
% Do a DC Correction on the data.  This method is a frequency domain
% operation.
% 
% INPUTS:
% in	= input data in matlab structure format.  
% mode	= ppmrange('p') or Value('v').  In ppmrange mode, the DC offset is
%           calculated automatically over a defined ppm range in the 
%           spectrum.  In value mode, the user has to provide the value of 
%           the desired DC offset.
% var1	= If mode is 'p', then 'var1' is the range of ppm values 
%           [minppm maxppm] over which to calculate the DC offset.  In 
%           ppmrange mode, the 'var1' is optional, and takes a default 
%           value of [max(in.ppm)-0.5 max(in.ppm] AND 
%           [min(in.ppm) min(in.ppm)+0.5].  If mode is 'v', then 'var1' is 
%           the value of the dc offset correction that you wish to employ.
%
% OUTPUTS:
% out   = Output following DC correction.  

function [out,dcOffset]=op_dccorr(in,mode,var1);

if mode=='p'
    if nargin<3
        var1a=[max(in.ppm)-0.5 max(in.ppm)];
        var1b=[min(in.ppm) min(in.ppm)+0.5];
        dcOffset1=mean(in.specs(in.ppm<var1a(2) & in.ppm>var1a(1)));
        dcOffset2=mean(in.specs(in.ppm<var1b(2) & in.ppm>var1b(1)));
        dcOffset=mean([dcOffset1 dcOffset2]);
    else
        dcOffset=mean(in.specs(in.ppm<var1(2) & in.ppm>var1(1)));
    end
elseif mode=='v'
    dcOffset=var1;
end

specs=in.specs-dcOffset;

%convert back to time domain
%if the length of Fids is odd, then you have to do a circshift of one to
%make sure that you don't introduce a small frequency shift into the fids
%vector.
if mod(size(specs,in.dims.t),2)==0
    %disp('Length of vector is even.  Doing normal conversion');
    fids=ifft(fftshift(specs,in.dims.t),[],in.dims.t);
else
    %disp('Length of vector is odd.  Doing circshift by 1');
    fids=ifft(circshift(fftshift(specs,in.dims.t),1),[],in.dims.t);
end

%FILLING IN DATA STRUCTURE
out=in;
out.fids=fids;
out.specs=specs;

%FILLING IN THE FLAGS
out.flags=in.flags;
out.flags.writtentostruct=1;
out.flags.freqranged=1;% op_lorentz.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% y=op_lorentz(pars,ppm);
% 
% DESCRIPTION:  
% Generate a parametrized lorentzian peak.
% This function is fed into fitting tools to enable fitting of peaks using
% lorentzian lineshapes.
% 
% INPUTS:
% pars       = The parameters of the Lorentizan function.  This is a five 
%             element vector consisting of the following fields:
%             [ Amplitude, 
%               FWHM, (In Hz) 
%               Centre Freq,  (In ppm)
%               baseline offset, (in Amplitude units)
%               Phase shift];  (in degrees)
% ppm        = frequency axis vector (in ppm);
%
% OUTPUTS:
% y          = Output vector specifying a lorentzian lineshape.  



function [y]=op_lorentz(pars,ppm)

A=pars(:,1);     %Amplitude  (Use only positive Numbers)
w=pars(:,2);     %full width at half max
ppm0=pars(:,3);  %centre frequency of peak

if size(pars,2)==5
    y0=pars(:,4);    %baseline offset
    theta=pars(:,5); %Phase shift of peak
    gam=w/2;      %gamma parameter
    %Define a complex lorentzian for each set of
    y=zeros(length(A),length(ppm));
    for n=1:length(A)
        y(n,:) = sqrt(2/pi) *(gam(n)-i*(ppm-ppm0(n))) ./ (gam(n)^2 + (ppm-ppm0(n)).^2);
        %now scale it, add baseline, phase it by theta, and take the real part
        y(n,:)=real(addphase(y(n,:)/max(abs(y(n,:)))*A(n)+y0(n),theta(n)));
    end
    y=sum(y,1);
elseif size(pars,2)==4
    y0=pars(:,4);    %baseline offset
    gam=w/2;      %gamma parameter
    %assume zero phase:
    theta=zeros(size(pars,1),1);
    %Define a complex lorentzian for each set of
    y=zeros(length(A),length(ppm));
    for n=1:length(A)
        y(n,:) = sqrt(2/pi) *(gam(n)-i*(ppm-ppm0(n))) ./ (gam(n)^2 + (ppm-ppm0(n)).^2);
        %now scale it, add baseline, phase it by theta, and take the real part
